import{c as t,Q as n,j as a,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"IndexMem: Learned KV-Cache Eviction with Latent Memory for Long-Context LLM Inference","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.25475","title":"IndexMem: Learned KV-Cache Eviction with Latent Memory for Long-Context LLM Inference","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2605.25475,"authors":["Xintong Yang","Hao Gu","Binxing Xu","Lujun Li","Bei Liu","Jiacheng Liu","Qiyuan Zhu","Sirui Han","Yike Guo"],"domains":["cs.CL","KV cache"],"html":"https://arxiv.org/html/2605.25475v1","pdf_path":"pdfs/2605.25475.pdf","published_date":"2026-05-25T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-05-25-indexmem-learned-kv-cache-eviction-2605-25475.md","filePath":"research/papers/2026-05-25-indexmem-learned-kv-cache-eviction-2605-25475.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-05-25-indexmem-learned-kv-cache-eviction-2605-25475.md"};function i(s,e,c,l,d,h){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="indexmem-learned-kv-cache-eviction-with-latent-memory-for-long-context-llm-inference" tabindex="-1">IndexMem: Learned KV-Cache Eviction with Latent Memory for Long-Context LLM Inference <a class="header-anchor" href="#indexmem-learned-kv-cache-eviction-with-latent-memory-for-long-context-llm-inference" aria-label="Permalink to &quot;IndexMem: Learned KV-Cache Eviction with Latent Memory for Long-Context LLM Inference&quot;">​</a></h1><p><strong>Authors</strong>: Xintong Yang, Hao Gu, Binxing Xu, Lujun Li, Bei Liu, Jiacheng Liu, Qiyuan Zhu, Sirui Han, Yike Guo <strong>Published</strong>: May 25, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2605.25475" target="_blank" rel="noreferrer">https://arxiv.org/abs/2605.25475</a> · <a href="https://arxiv.org/html/2605.25475v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2605.25475 <strong>Categories</strong>: cs.CL <strong>PDF</strong>: <a href="https://arxiv.org/abs/2605.25475" target="_blank" rel="noreferrer">research/papers/pdfs/2605.25475.pdf</a> (18 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Large Language Models (LLMs) are increasingly expected to operate over long contexts, yet standard softmax attention incurs a KV cache that grows linearly with sequence length, quickly becoming the bottleneck for long context inference. A practical remedy is to evict less important KV entries; however, existing eviction policies are largely heuristic and struggle to capture the rich, input-dependent distribution of token importance. In this work, we introduce a learnable indexer that predicts KV importance, enabling more accurate retention of critical tokens. Meanwhile, naively evicting tokens permanently discards their information, leading to irreversible forgetting and degraded retrieval over long ranges. To address this, we propose a lightweight latent memory module that compresses evicted tokens into a compact, online-updated state and provides residual readouts to compensate for the attention contributions lost through KV eviction. Collectively, our method enables accurate long-context inference under a bounded KV budget, delivering consistent improvements on RULER (4K/16K) across Qwen, Mistral, and Llama models (up to 25 points under aggressive eviction), markedly more stable Needle-in-a-Haystack retrieval, and superior LongBench scores and compression curves compared to existing eviction policies.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li><strong>Learned KV eviction</strong>：以可學習的 indexer 預測每個 token 的 KV 重要性，取代現有啟發式 eviction policy（如 attention score threshold），使留存決策隨輸入分佈動態調整。</li><li><strong>Latent memory module</strong>：被 evict 的 KV 不直接丟棄，而是壓縮進一個 lightweight、online-updated 的 latent state；attention 計算時提供 residual readout，補償 eviction 造成的注意力損失，緩解不可逆遺忘問題。</li><li><strong>Bounded KV budget 推論</strong>：整體架構在記憶體上限固定的條件下，讓 long-context LLM 保持穩定推理品質，適用於 Qwen、Mistral、Llama 等主流架構。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>RULER benchmark（4K/16K context）：在 aggressive eviction 設定下，相較 baseline eviction policy 提升最多 <strong>25 points</strong>。</li><li>Needle-in-a-Haystack 檢索任務：穩定性顯著優於現有 eviction 方法（量化數字未明列，論文以曲線呈現）。</li><li>LongBench：compression curve（KV budget vs. 性能）全程優於對比方案。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>Learned indexer 需要額外訓練（fine-tuning 或 plug-in 訓練），對已部署模型的整合成本未詳述。</li><li>Latent memory 的 online update 機制在極長序列（&gt;100K tokens）下的延遲與記憶體開銷未量化。</li><li>實驗限於 decoder-only 架構（Qwen/Mistral/Llama），encoder-decoder 或 MoE 模型適用性未驗證。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>context-management.md 的 NLAH 原則</strong>：本論文的 KV eviction + latent memory 機制與 &quot;Right context &gt; more context&quot; 理念高度對應——保留 critical tokens、壓縮低重要性 token，是 inference 層的 NLAH 實踐；⚠️ 兩者作用層不同（模型推理 vs. prompt 工程），不可直接互換。</li><li><strong>memory-compactor 概念</strong>：latent memory module 的「壓縮被捨棄資訊為 compact state」思路，與 workspace 的 memory compactor（跨 session 壓縮 context）在設計意圖上相似；⚠️ 落地門檻高，workspace memory 為 text-level 操作，此論文為 embedding-level，實作路徑不同。</li><li><strong>unverified_success 閘門</strong>：論文以 RULER/LongBench 等 benchmark 驗證，但 benchmark 覆蓋的 task 分佈不等於生產推理場景；引用結果前應視為 <code>unverified_success</code>，需在目標模型與 context 長度下親自重跑確認。</li><li><strong>token budget 管理</strong>：研究結論可作為設計「何時/如何截斷長 context」策略的理論依據，與 context-management.md 的 token budget 軟性門檻互為參照；⚠️ 直接套用需對應模型支援 IndexMem 的 learned indexer。</li></ul>',16)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
